    const patrolHit=new THREE.Mesh(new THREE.BoxGeometry(1.55,1.30,.18),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));
    patrolHit.position.set(19,1.38,1.58);
