    const logBookHit=new THREE.Mesh(new THREE.BoxGeometry(1.20,.72,.78),new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false}));
    logBookHit.position.set(18.98,1.10,1.42);
